// Unshown render-only WPF tests; injected display API only, no native display operations.
using System;using System.Collections.Generic;using System.Linq;using System.Reflection;using System.Windows;using System.Windows.Controls;using System.Windows.Media;using RogControl;
internal static class WindowsDisplayGuiTests {
 const string One=@"\\.\DISPLAY1",Two=@"\\.\DISPLAY2";
 static readonly BindingFlags Hidden=BindingFlags.Instance|BindingFlags.NonPublic;
 static int Count;
 static void Check(bool value,string name){if(!value)throw new Exception("FAIL "+name);Count++;}
 static void Set(MainWindow w,string field,object value){typeof(MainWindow).GetField(field,Hidden).SetValue(w,value);}
 static object Get(MainWindow w,string field){return typeof(MainWindow).GetField(field,Hidden).GetValue(w);}
 static object Invoke(MainWindow w,string method,params object[] args){return typeof(MainWindow).GetMethod(method,Hidden).Invoke(w,args);}
 static IEnumerable<DependencyObject> Walk(DependencyObject root){yield return root;for(int i=0;i<VisualTreeHelper.GetChildrenCount(root);i++)foreach(var child in Walk(VisualTreeHelper.GetChild(root,i)))yield return child;}
 static FrameworkElement Render(MainWindow window,int width){Invoke(window,"ShowPage","屏幕设置");var root=(FrameworkElement)window.Content;root.Measure(new Size(width,826));root.Arrange(new Rect(0,0,width,826));root.UpdateLayout();return root;}
 static DisplayNativeDevice Device(string name,string id,string label,uint flags){return new DisplayNativeDevice{cb=840,DeviceName=name,DeviceID=id,DeviceString=label,StateFlags=flags};}
 static DisplayNativeMode Mode(uint hz){return new DisplayNativeMode{dmSize=220,dmFields=WindowsDisplayRules.RequiredModeFields|WindowsDisplayRules.DmOrientation|WindowsDisplayRules.DmFlags|WindowsDisplayRules.DmPosition,dmPelsWidth=1920,dmPelsHeight=1080,dmBitsPerPel=32,dmDisplayFrequency=hz};}
 sealed class Fake:IWindowsDisplayApi {
  public int Reads,Tests,Writes;public bool MissingFirst;public uint FirstRate=60;
  public bool EnumDevice(string parent,uint index,uint flags,out DisplayNativeDevice device){Reads++;device=new DisplayNativeDevice();if(parent==null){if(index>1)return false;device=Device(index==0?One:Two,"adapter","合成 GPU",index==0?5u:1u);return true;}if(index>0)return false;device=Device(parent+@"\Monitor0",parent==One?"monitor-a":"monitor-b","合成屏幕",1);return true;}
  public bool EnumMode(string name,uint index,out DisplayNativeMode mode){Reads++;mode=new DisplayNativeMode();if(index==WindowsDisplayRules.EnumCurrent){if(name==One&&MissingFirst)return false;mode=Mode(name==One?FirstRate:75);return true;}if(index>1)return false;mode=Mode(index==0?60u:120u);return true;}
  public DisplayPathInfo[] ActivePaths(){Reads++;return new[]{new DisplayPathInfo{SourceDeviceName=One,MonitorDevicePath="monitor-a",FriendlyName="合成显示器 A",Active=true,TargetAvailable=true,Rotation=1,RefreshNumerator=FirstRate==60?60000u:FirstRate,RefreshDenominator=FirstRate==60?1001u:1u},new DisplayPathInfo{SourceDeviceName=Two,MonitorDevicePath="monitor-b",FriendlyName="合成显示器 B",Active=true,TargetAvailable=true,Rotation=1,RefreshNumerator=75,RefreshDenominator=1}};}
  public int ChangeMode(string name,ref DisplayNativeMode mode,uint flags){if(flags==WindowsDisplayRules.CdsTest){Tests++;return 0;}Writes++;if(name==One)FirstRate=mode.dmDisplayFrequency;return 0;}
 }
 [STAThread]public static int Main(){try{
  var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};var window=new MainWindow(true);var api=new Fake();var controller=new WindowsDisplayController(api);Set(window,"windowsDisplayController",controller);var snapshot=controller.Read();Invoke(window,"SetWindowsDisplayRead",snapshot);var drafts=(Dictionary<string,uint>)Get(window,"windowsDisplayDraft");var first=snapshot.Screens.Single(s=>s.DeviceName==One);var second=snapshot.Screens.Single(s=>s.DeviceName==Two);
  Check(drafts[first.Id]==60,"enumerated current is default draft");Check(drafts[second.Id]==60,"current absent from candidates falls back to firstsupported");
  foreach(int width in new[]{1180,1538}){var root=Render(window,width);var nodes=Walk(root).ToArray();var labels=nodes.OfType<TextBlock>().Select(t=>t.Text).ToArray();Check(labels.Contains("1920 × 1080 · 60 Hz"),"integer current mode text at "+width);Check(labels.Contains("时序刷新率：59.94 Hz"),"rational timing stays separate at "+width);var combos=nodes.OfType<ComboBox>().ToArray();Check(combos.Length==2&&combos.All(c=>c.Items.Count==2),"only both screens' enumerated rate selectors at "+width);for(int i=0;i<combos.Length;i++){var selected=(ComboBoxItem)combos[i].SelectedItem;var screen=snapshot.Screens[i];Check(selected!=null&&(uint)selected.Tag==drafts[screen.Id],"visual selection equals real draft "+width+"/"+i);Check(combos[i].ActualWidth<width-248-44,"selector fits original content width "+width+"/"+i);}Check(!combos[0].Items.Cast<ComboBoxItem>().Any(item=>Convert.ToString(item.Content).Contains("59.94")),"integer candidates do not invent fractional modes");Check(nodes.OfType<Button>().Where(b=>Convert.ToString(b.Content)=="应用刷新率").All(b=>!b.IsEnabled),"defaultoff render page cannot apply");int writes=api.Writes,tests=api.Tests;combos[0].SelectedIndex=1;Check(drafts[first.Id]==120&&api.Writes==writes&&api.Tests==tests,"selection remains draft only "+width);Invoke(window,"SetWindowsDisplayRead",snapshot);Check(drafts[first.Id]==120,"valid user draft survives refresh");drafts[first.Id]=999;Invoke(window,"SetWindowsDisplayRead",snapshot);Check(drafts[first.Id]==60,"invalid saved draft normalizes to current");}
  int reads=api.Reads;((System.Threading.Tasks.Task)Invoke(window,"ReadWindowsDisplay")).GetAwaiter().GetResult();((System.Threading.Tasks.Task)Invoke(window,"ChangeWindowsDisplay",first)).GetAwaiter().GetResult();Check(api.Reads==reads&&api.Tests==0&&api.Writes==0,"render callbacks do not start hardware work");
  Check(Get(window,"windowsDisplay")!=null&&drafts.Count==2,"nonempty current before missing readback regression");Invoke(window,"WindowsDisplayChanged",new WindowsDisplayChangeResult{Error="合成连接断开",OriginalMode=first.CurrentMode});Check(Get(window,"windowsDisplay")==null&&drafts.Count==0,"missing observed screen clears old current snapshot");var missingNodes=Walk(Render(window,1180)).ToArray();Check(missingNodes.OfType<Button>().Any(b=>Convert.ToString(b.Content)=="刷新")&&!missingNodes.OfType<TextBlock>().Any(t=>t.Text=="1920 × 1080 · 60 Hz"),"missing readback does not display old current and keeps refresh");Check(missingNodes.OfType<TextBlock>().Any(t=>t.Text=="应用未确认：合成连接断开"),"missing readback keeps the actual failure message");Invoke(window,"SetWindowsDisplayRead",snapshot);
  drafts[first.Id]=999;var normalized=Walk(Render(window,1180)).OfType<ComboBox>().First();Check((uint)((ComboBoxItem)normalized.SelectedItem).Tag==drafts[first.Id]&&drafts[first.Id]==60,"render normalizes invalid draft without SelectionChanged race");
  api.MissingFirst=true;var unknown=controller.Read();Invoke(window,"WindowsDisplayChanged",new WindowsDisplayChangeResult{ObservedScreen=unknown.Screens.First(s=>s.DeviceName==One),Error="synthetic missing mode"});Check(drafts[first.Id]==0,"missing observed CurrentMode safely resets draft to0");var unknownNodes=Walk(Render(window,1180)).ToArray();var unknownCombo=unknownNodes.OfType<ComboBox>().First();Check(unknownCombo.Items.Count==0&&unknownCombo.SelectedIndex==-1&&!unknownCombo.IsEnabled,"unknown mode has no false selected candidate");Check(unknownNodes.OfType<TextBlock>().Any(t=>t.Text=="应用未确认：synthetic missing mode"),"unknown result stays an unconfirmed message");
  api.MissingFirst=false;snapshot=controller.Read();Invoke(window,"SetWindowsDisplayRead",snapshot);first=snapshot.Screens.First(s=>s.DeviceName==One);var changed=controller.ApplyRefreshRate(first,120,true);Check(changed.ReadbackConfirmed&&changed.RestorePoint!=null&&api.Writes==1,"manual receipt fixture uses fake mutation only");Invoke(window,"WindowsDisplayChanged",changed);Check(Object.ReferenceEquals(Get(window,"windowsDisplayUndo"),changed.RestorePoint),"GUI retains confirmed manual restore ownership");Check(drafts[first.Id]==120,"confirmed observed rate replaces the previous draft");Check(!window.CanPreviewReload,"restore point blocks preview replacement");var undoNodes=Walk(Render(window,1180)).ToArray();Check(undoNodes.OfType<Button>().Any(b=>Convert.ToString(b.Content)=="恢复修改前的刷新率"),"manual restore remains visible");Invoke(window,"WindowsDisplayChanged",new WindowsDisplayChangeResult{Error="合成恢复读回失败"});Check(Get(window,"windowsDisplay")==null&&Object.ReferenceEquals(Get(window,"windowsDisplayUndo"),changed.RestorePoint),"missing current keeps an independently confirmed recovery point");Check(!window.CanPreviewReload,"unresolved recovery ownership still blocks preview");undoNodes=Walk(Render(window,1180)).ToArray();Check(undoNodes.OfType<Button>().Any(b=>Convert.ToString(b.Content)=="恢复修改前的刷新率"),"restore remains reachable without a current snapshot");int fakeWrites=api.Writes;var keep=undoNodes.OfType<Button>().Single(b=>Convert.ToString(b.Content)=="保留当前刷新率");keep.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Check(Get(window,"windowsDisplayUndo")==null&&api.Writes==fakeWrites,"explicit keep clears receipt without a setter");Check(window.CanPreviewReload,"keep permits preview replacement");Invoke(window,"SetWindowsDisplayRead",controller.Read());
  Set(window,"windowsSystemWriting",true);Check(!window.CanPreviewReload,"pending display write blocks preview replacement");Set(window,"windowsSystemWriting",false);Set(window,"windowsSystemTask",new System.Threading.Tasks.TaskCompletionSource<bool>().Task);Check(!window.CanPreviewReload,"pending system task blocks preview replacement");Set(window,"windowsSystemTask",null);
  Check(Get(window,"windowsDisplay")!=null&&drafts.Count>0,"nonempty current before null snapshot regression");Invoke(window,"SetWindowsDisplayRead",new object[]{null});Check(drafts.Count==0&&Get(window,"windowsDisplay")==null,"null snapshot cannot retain stale draft");Invoke(window,"SetWindowsDisplayRead",snapshot);Check(Get(window,"windowsDisplay")!=null&&drafts.Count>0,"nonempty current before null result regression");Invoke(window,"WindowsDisplayChanged",new object[]{null});Check(Get(window,"windowsDisplay")==null&&drafts.Count==0&&Convert.ToString(Get(window,"windowsDisplayMessage")).Contains("未返回"),"null result clears stale current without throwing");
  window.Close();app.Shutdown();Console.WriteLine("PASS "+Count+" GUI checks; real display GET/TEST/write=0; shown windows=0; fake writes="+api.Writes);return 0;
 }catch(Exception e){Console.Error.WriteLine(e.InnerException??e);return 1;}}
}
